1407	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
1408	func (s *Store) persist(st *persistedState) error {
1409		data, err := json.MarshalIndent(st, "", "  ")
1410		if err != nil {
1411			return err
1412		}
1413		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
1414		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
1415		if err != nil {
1416			return err
1417		}
1418		if _, err := f.Write(data); err != nil {
1419			f.Close()
1420			return err
1421		}
1422		if err := f.Sync(); err != nil {
1423			f.Close()
1424			return err
1425		}
1426		if err := f.Close(); err != nil {
1427			return err
1428		}
1429		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
1430			return err
1431		}
1432		if d, err := os.Open(s.dir); err == nil {
1433			_ = d.Sync()
1434			_ = d.Close()
1435		}
1436		return nil
1437	}
