1454	// write 是所有写入操作的统一入口：
1455	//   - reqNo 为空直接报错；
1456	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
1457	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
1458	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
1459	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
1460	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
1461		if reqNo == "" {
1462			return errors.New("请求编号不能为空")
1463		}
1464		s.mu.Lock()
1465		defer s.mu.Unlock()
1466		if err := s.lockExclusive(); err != nil {
1467			return err
1468		}
1469		defer s.unlock()
1470	
1471		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
1472		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
1473		if err := s.load(); err != nil {
1474			return err
1475		}
1476	
1477		payloadRaw, err := json.Marshal(payload)
1478		if err != nil {
1479			return err
1480		}
1481		payloadStr := string(payloadRaw)
1482	
1483		if req, ok := s.state.Requests[reqNo]; ok {
1484			if req.Op != op || req.Payload != payloadStr {
1485				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
1486					ErrRequestConflict, reqNo, req.Op, op)
1487			}
1488			// 保存的配方登记结果、创建批次结果、草稿调整结果、投料结果、开始执行
1489			// 结果与关闭结果都已在本次 load 的 validateState 中与实际登记内容核对
1490			// 一致（缺失、为 null、为空对象或内容不符都已在上面拒绝），这里取回的
1491			// 就是第一次成功的结果。
1492			if err := json.Unmarshal(req.Result, out); err != nil {
1493				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
1494			}
1495			return nil
1496		}
1497	
1498		clone, err := cloneState(s.state)
1499		if err != nil {
1500			return err
1501		}
1502		result, err := apply(clone)
1503		if err != nil {
1504			return err
1505		}
1506		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
1507		if err := s.persist(clone); err != nil {
1508			return fmt.Errorf("保存台账失败: %w", err)
1509		}
1510		s.state = clone
1511		if err := json.Unmarshal(result, out); err != nil {
1512			return fmt.Errorf("解析请求结果失败: %w", err)
1513		}
1514		return nil
1515	}
