1517	// read 在共享锁下读取当前状态。
1518	func (s *Store) read(fn func(*persistedState) error) error {
1519		s.mu.Lock()
1520		defer s.mu.Unlock()
1521		if err := s.lockShared(); err != nil {
1522			return err
1523		}
1524		defer s.unlock()
1525		if err := s.load(); err != nil {
1526			return err
1527		}
1528		return fn(s.state)
1529	}
