// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
func (s *Store) persist(st *persistedState) error {
	data, err := json.MarshalIndent(st, "", "  ")
	if err != nil {
		return err
	}
	tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
	f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	if _, err := f.Write(data); err != nil {
		f.Close()
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
		return err
	}
	if d, err := os.Open(s.dir); err == nil {
		_ = d.Sync()
		_ = d.Close()
	}
	return nil
}

func cloneState(st *persistedState) (*persistedState, error) {
	data, err := json.Marshal(st)
	if err != nil {
		return nil, err
	}
	var out persistedState
	if err := json.Unmarshal(data, &out); err != nil {
		return nil, err
	}
	if out.Requests == nil {
		out.Requests = map[string]*requestRecord{}
	}
	return &out, nil
}

// write 是所有写入操作的统一入口：
//   - reqNo 为空直接报错；
//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
	if reqNo == "" {
		return errors.New("请求编号不能为空")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.lockExclusive(); err != nil {
		return err
	}
	defer s.unlock()

	// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
	// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
	if err := s.load(); err != nil {
		return err
	}

	payloadRaw, err := json.Marshal(payload)
	if err != nil {
		return err
	}
	payloadStr := string(payloadRaw)

	if req, ok := s.state.Requests[reqNo]; ok {
		if req.Op != op || req.Payload != payloadStr {
			return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
				ErrRequestConflict, reqNo, req.Op, op)
		}
		// 保存的配方登记结果、创建批次结果、草稿调整结果、投料结果、开始执行
		// 结果与关闭结果都已在本次 load 的 validateState 中与实际登记内容核对
		// 一致（缺失、为 null、为空对象或内容不符都已在上面拒绝），这里取回的
		// 就是第一次成功的结果。
		if err := json.Unmarshal(req.Result, out); err != nil {
			return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
		}
		return nil
	}

	clone, err := cloneState(s.state)
	if err != nil {
		return err
	}
	result, err := apply(clone)
	if err != nil {
		return err
	}
	clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
	if err := s.persist(clone); err != nil {
		return fmt.Errorf("保存台账失败: %w", err)
	}
	s.state = clone
	if err := json.Unmarshal(result, out); err != nil {
		return fmt.Errorf("解析请求结果失败: %w", err)
	}
	return nil
}

// read 在共享锁下读取当前状态。
func (s *Store) read(fn func(*persistedState) error) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.lockShared(); err != nil {
		return err
	}
	defer s.unlock()
	if err := s.load(); err != nil {
		return err
	}
	return fn(s.state)
}

// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。

func buildRecipeView(r *recipeRecord) *RecipeView {
	mats := make([]MaterialView, 0, len(r.Materials))
	for _, m := range r.Materials {
		mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
	}
	return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
}

func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
	v := &BatchView{
		BatchNo:         b.BatchNo,
		RecipeNo:        r.RecipeNo,
		RecipeVersion:   r.Version,
		RecipeName:      r.Name,
		PlannedPortions: b.PlannedPortions,
		Status:          b.Status,
		Feedings:        make([]FeedingView, 0, len(b.Feedings)),
		Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
	}

	for _, f := range b.Feedings {
		v.Feedings = append(v.Feedings, FeedingView{
			Seq:        f.Seq,
			MaterialNo: f.MaterialNo,
			Grams:      f.GramsMilli.String(),
			Time:       f.Time,
			Registrar:  f.Registrar,
		})
	}

	// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
	// 这里仍用同一套累计规则防一手整数回绕。
	acc := newFeedingAccumulator()
	for _, f := range b.Feedings {
		if !acc.add(f.MaterialNo, f.GramsMilli) {
			return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
				ErrCorruptData, b.BatchNo, f.MaterialNo)
		}
	}

	// 数量核对按配方物料逐项列出；应投量统一由 planRequirements 按本批次
	// 绑定版本与计划份数计算，与创建、调整、读取校验共用同一套规则。
	// 台账在读取时已通过 validateState 校验，这里仍防一手同一版本内物料
	// 编号重复，避免返回重复的数量核对项。
	required, err := planRequirements(r, b.PlannedPortions)
	if err != nil {
		return nil, fmt.Errorf("%w: 批次 %q 的%v", ErrCorruptData, b.BatchNo, err)
	}
	seen := make(map[string]bool, len(required))
	for _, item := range required {
		if seen[item.materialNo] {
			return nil, fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
				ErrCorruptData, r.RecipeNo, r.Version, item.materialNo)
		}
		seen[item.materialNo] = true
		act := acc.total(item.materialNo)
		v.Materials = append(v.Materials, MaterialRequirement{
			MaterialNo:      item.materialNo,
			RequiredGrams:   item.requiredGrams.String(),
			ActualGrams:     act.String(),
			DifferenceGrams: (act - item.requiredGrams).String(),
		})
	}
	return v, nil
}

// recipeKey 是配方的唯一标识：配方编号与版本号的组合，采用精确匹配。
type recipeKey struct {
	recipeNo string
	version  string
}

func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
	for _, r := range st.Recipes {
		if r.RecipeNo == recipeNo && r.Version == version {
			return r
		}
	}
	return nil
}

func findBatch(st *persistedState, batchNo string) *batchRecord {
	for _, b := range st.Batches {
		if b.BatchNo == batchNo {
			return b
		}
	}
	return nil
}

package release

import "fmt"

// plannedMaterial 是数量核对规则对配方中一种物料的计算结果：
// 物料编号及其在当前计划份数下的应投量（千分之一克）。
type plannedMaterial struct {
	materialNo    string
	requiredGrams gramsMilli
}

// planRequirements 是批次“应投量核对”数量规则的唯一实现：给定批次采用
// 的配方版本 r 与最终采用的计划份数 portions，按配方中的物料顺序逐项计算
// 每份克数 × 计划份数，返回每种物料的应投量。
//
// 规则对创建批次、调整草稿、读取已保存批次和构造批次查询结果完全一致：
//   - 份数必须为正整数。份数的输入语义由各入口自行处理——创建要求正整数，
//     调整草稿时传 0 表示沿用当前份数（走到这里的必是最终正份数），读取
//     已保存批次时份数非正属于数据损坏；本函数只接受已确定的最终份数；
//   - 结果必须能精确表示到千分之一克：每份克数本身已是千分之一克的整数倍，
//     整数相乘不引入更小单位，不舍入、不截断；
//   - 每种物料分别以 maxGramsMilli（9223372036854775.807 克）为上限：
//     只乘该物料自己的每份克数与份数，不与同批次其他物料的应投量相加，
//     恰好等于上限合法，超过即返回错误。错误信息指出相关物料、配方编号、
//     版本与份数；调用方再按各自场景包装错误分类（提交时为
//     ErrInvalidInput，读取已保存批次时为 ErrCorruptData 并补充批次编号）。
//
// 不能改用同编号配方的其他版本：物料列表与每份克数一律取调用方给定的 r，
// 即批次实际绑定（或本次提交最终选定）的版本。
func planRequirements(r *recipeRecord, portions int) ([]plannedMaterial, error) {
	out := make([]plannedMaterial, 0, len(r.Materials))
	for _, m := range r.Materials {
		required, err := multiplyPortions(m.GramsMilli, portions)
		if err != nil {
			return nil, fmt.Errorf("物料 %q 按配方 %q 版本 %q 以 %d 份计算的应投量不合法: %v",
				m.MaterialNo, r.RecipeNo, r.Version, portions, err)
		}
		out = append(out, plannedMaterial{materialNo: m.MaterialNo, requiredGrams: required})
	}
	return out, nil
}

package release

import (
	"encoding/json"
	"errors"
	"time"
)

// BatchStatus 表示批次状态。
type BatchStatus string

const (
	// StatusDraft 草稿：可以调整计划份数或改选配方版本。
	StatusDraft BatchStatus = "draft"
	// StatusExecuting 执行中：份数与配方已固定，可追加投料。
	StatusExecuting BatchStatus = "executing"
	// StatusClosed 已关闭：确认已有投料，不可再追加或重新打开。
	StatusClosed BatchStatus = "closed"
)

// validBatchStatus 是已保存批次状态允许出现的全部取值，必须精确匹配。
// 读取台账时状态只能是这三个字符串之一：缺失、为空、null、其他字符串，
// 或大小写不同、前后多出空格的近似写法都不自动归入某个合法状态。
var validBatchStatus = map[BatchStatus]bool{
	StatusDraft:     true,
	StatusExecuting: true,
	StatusClosed:    true,
}

// isValidBatchStatus 判断已保存批次状态是否精确对应一个合法状态。
// 只做逐字符的精确匹配，不做大小写归一化或去空格："Draft"、" draft "
// 等写法与 "ready"、空字符串一样属于无法识别的状态。
func isValidBatchStatus(s BatchStatus) bool {
	return validBatchStatus[s]
}

// MaterialInput 是登记配方时的物料输入。
type MaterialInput struct {
	// MaterialNo 物料编号，同一配方版本内不可重复。
	MaterialNo string
	// Grams 生产一份该物料需要的克数，必须为正数且最多三位小数。
	Grams string
}

// MaterialView 是配方物料的查询视图。
type MaterialView struct {
	MaterialNo string
	Grams      string
}

// RecipeView 是配方版本的查询视图。
type RecipeView struct {
	RecipeNo  string
	Version   string
	Name      string
	Materials []MaterialView
}

// FeedingView 是一条投料记录的查询视图。
type FeedingView struct {
	Seq        int       // 投料登记顺序，从 1 开始
	MaterialNo string    // 物料编号（必然属于该批次绑定的配方版本）
	Grams      string    // 本次投料克数
	Time       time.Time // 投料时间（由调用方填写，不参与排序）
	Registrar  string    // 登记人
}

// MaterialRequirement 是按物料逐项列出的数量核对结果。
type MaterialRequirement struct {
	MaterialNo      string
	RequiredGrams   string // 应投量 = 每份克数 × 计划份数
	ActualGrams     string // 累计实投量（仅统计该物料的投料）
	DifferenceGrams string // 实投减应投（可能为负；物料之间不互相抵消）
}

// BatchView 是批次查询视图。
type BatchView struct {
	BatchNo         string
	RecipeNo        string
	RecipeVersion   string
	RecipeName      string
	PlannedPortions int
	Status          BatchStatus
	Feedings        []FeedingView         // 按成功登记的先后顺序排列
	Materials       []MaterialRequirement // 配方中每种物料一项，无投料也显示
}

// 导出的错误。调用方可以用 errors.Is 判定类别，
// 具体原因会通过 fmt.Errorf("%w: ...") 附带在错误信息中。
var (
	// ErrNotFound 查询的批次或配方版本不存在。
	ErrNotFound = errors.New("未找到")
	// ErrDuplicateBatch 批次编号已存在。
	ErrDuplicateBatch = errors.New("批次编号重复")
	// ErrRecipeExists 配方版本已登记，内容不可覆盖。
	ErrRecipeExists = errors.New("配方版本已存在，不可覆盖")
	// ErrInvalidInput 输入不合法（编号为空、克数非法、份数非正整数等）。
	ErrInvalidInput = errors.New("输入不合法")
	// ErrInvalidState 当前批次状态不允许该操作。
	ErrInvalidState = errors.New("当前状态不允许该操作")
	// ErrMaterialNotInRecipe 投料物料不属于该批次绑定的配方版本。
	ErrMaterialNotInRecipe = errors.New("物料不属于该批次的配方版本")
	// ErrRequestConflict 请求编号已被用于其他操作或不同内容。
	ErrRequestConflict = errors.New("请求编号冲突")
	// ErrCorruptData 台账数据已损坏或无法读取，不能当成空台账继续。
	ErrCorruptData = errors.New("台账数据损坏，无法读取")
)

// 内部持久化记录。

type materialRecord struct {
	MaterialNo string     `json:"materialNo"`
	GramsMilli gramsMilli `json:"gramsMilli"`
}

type recipeRecord struct {
	RecipeNo  string           `json:"recipeNo"`
	Version   string           `json:"version"`
	Name      string           `json:"name"`
	Materials []materialRecord `json:"materials"`
}

type feedingRecord struct {
	Seq        int        `json:"seq"`
	MaterialNo string     `json:"materialNo"`
	GramsMilli gramsMilli `json:"gramsMilli"`
	Time       time.Time  `json:"time"`
	Registrar  string     `json:"registrar"`
}

type batchRecord struct {
	BatchNo         string          `json:"batchNo"`
	RecipeNo        string          `json:"recipeNo"`
	RecipeVersion   string          `json:"recipeVersion"`
	PlannedPortions int             `json:"plannedPortions"`
	Status          BatchStatus     `json:"status"`
	Feedings        []feedingRecord `json:"feedings"`
}

type requestRecord struct {
	Op      string          `json:"op"`
	Payload string          `json:"payload"`
	Result  json.RawMessage `json:"result"`
}

type persistedState struct {
	Version  int                       `json:"version"`
	Recipes  []*recipeRecord           `json:"recipes"`
	Batches  []*batchRecord            `json:"batches"`
	Requests map[string]*requestRecord `json:"requests"`
}

