			}
			if gotVal != check.want {
				return fmt.Errorf("%w: %s %q（批次 %q）保存结果物料 %q 的%s %s 与应有值 %s 不一致",
					ErrCorruptData, opDesc, reqNo, batchNo, item.materialNo, check.name, check.got, check.want)
			}
		}
	}
	return nil
}

